/* 
  Excellent RESTful JSON Response Design
*/

// Request: GET /api/v1/articles

// Response: 200 OK
{
  // Wrap data in a 'data' object so you can easily add metadata later
  "data": [
    { "id": 1, "title": "REST Rules" },
    { "id": 2, "title": "APIs 101" }
  ],
  // Metadata (Pagination data is crucial!)
  "meta": {
    "total_count": 500,
    "current_page": 1,
    "has_next": true
  }
}
